package mz.bam.seeky.android;
import android.app.Application;import android.content.*;import android.database.Cursor;import android.net.Uri;import android.os.*;import org.json.*;import java.io.*;import java.nio.file.Files;import java.util.*;import java.util.zip.*;
import org.junit.*;import org.junit.runner.RunWith;import org.robolectric.*;import org.robolectric.annotation.*;import static org.junit.Assert.*;
@RunWith(RobolectricTestRunner.class) @Config(manifest=Config.NONE,sdk=33,application=Application.class) @LooperMode(LooperMode.Mode.PAUSED)
public class WorkspaceBackupTest {
 Context c;long material,course;File book,voice,archive;String source="Uma matéria com uma nota de revisão.";String uri;
 @Before public void setup()throws Exception{c=RuntimeEnvironment.getApplication();WorkspaceEpoch.value=0;WorkspaceEpoch.restoring=false;book=new File(StudyFileProvider.directory(c),UUID.randomUUID()+".txt");Files.write(book.toPath(),source.getBytes("UTF-8"));try(StudyStore db=new StudyStore(c)){course=db.save("courses",0,StudyStore.values("title","Curso de teste","description","","created",1));material=db.save("materials",0,StudyStore.values("title","Livro de teste","name","Livro.txt","mime","text/plain","path",book.getPath(),"hash",StudyFiles.hash(book),"bytes",book.length(),"progress",37,"created",1,"updated",2));db.save("notes",0,StudyStore.values("title","Nota de teste","body","Conteúdo da nota.","material",material,"segment",2,"created",1,"updated",2));}uri=StudyFileProvider.uri(c,material).toString();try(ReaderStore db=new ReaderStore(c)){StudyText draft=new StudyText(source);draft.mark(0,3,"highlight","");db.save(uri,2,source,draft);db.bookmark(uri,2,4,"Marcador de teste");}File folder=new File(c.getFilesDir(),"voice-notes");folder.mkdirs();voice=new File(folder,UUID.randomUUID()+".wav");VoiceToolsTest.writeWav(voice,new byte[]{1,0,2,0});try(PlusStore db=new PlusStore(c)){long collection=BookCategories.collection(db,"Teologia");db.save("book_collections",StudyStore.values("hash",StudyFiles.hash(book),"collection",collection));db.save("voice_notes",StudyStore.values("uri",uri,"material",material,"segment",2,"position",4,"title","Minha nota de voz","path",voice.getPath(),"created",1));db.save("ocr_text",StudyStore.values("uri",uri,"segment",2,"digest",StudyFiles.hash(book),"value","Texto reconhecido.","created",1));long bible=db.save("bible_sources",StudyStore.values("title","Bíblia local","created",1));db.save("bible_verses",StudyStore.values("source",bible,"book","Isaías","chapter",5,"verse",6,"value","Texto da passagem."));}c.getSharedPreferences("seeky",0).edit().putInt("reader_page_"+uri,2).putString("personal_api_key","test-only-backup-secret").apply();c.getSharedPreferences("books",0).edit().putStringSet("favorites",new HashSet<>(Arrays.asList(StudyFiles.hash(book)))).apply();c.getSharedPreferences("pronunciation",0).edit().putString("rules","[{\"word\":\"ONU\",\"say\":\"Organização das Nações Unidas\"}]").apply();c.getSharedPreferences("reading_tools",0).edit().putBoolean("ocr_present",true).apply();archive=new File(c.getCacheDir(),"workspace-fixture.zip");}
 void write()throws Exception{try(OutputStream out=new FileOutputStream(archive)){WorkspaceBackup.write(c,out,false,()->false,s->{});}}
 WorkspaceBackup.Staged stage()throws Exception{return WorkspaceBackup.stage(c,archive,false,()->false,s->{});}
 @Test public void completeArchiveContainsBooksNotesAndPreferencesButNoCredential()throws Exception{write();try(ZipFile zip=new ZipFile(archive);InputStream in=zip.getInputStream(zip.getEntry("workspace.json"))){String json=new String(ContentText.read(in,1000000),"UTF-8");assertFalse(json.contains("test-only-backup-secret"));assertFalse(json.contains("personal_api_key"));assertTrue(json.contains("favorites"));assertTrue(json.contains("pronunciation"));assertEquals(6,zip.size());}try(WorkspaceBackup.Staged staged=stage()){WorkspaceBackup.Info info=WorkspaceBackup.inspect(c,staged);assertEquals(1,info.books);assertEquals(1,info.courses);assertEquals(1,info.notes);assertEquals(2,info.files);}}
 @Test public void restorePreservesIdentitiesAndRemapsPrivateBooksAndVoiceNotes()throws Exception{write();try(StudyStore db=new StudyStore(c)){db.save("materials",material,StudyStore.values("progress",99));db.save("notes",0,StudyStore.values("title","Outra","body","Depois do backup.","created",3,"updated",3));}c.getSharedPreferences("seeky",0).edit().putInt("reader_page_"+uri,99).apply();try(WorkspaceBackup.Staged staged=stage()){WorkspaceBackup.restore(c,staged,()->false,s->{});}try(StudyStore db=new StudyStore(c)){assertEquals(37,db.get("materials",material).n("progress"));assertEquals(1,db.count("notes",null,null));File restored=new File(db.get("materials",material).s("path"));assertTrue(restored.isFile());assertNotEquals(book.getPath(),restored.getPath());assertEquals(StudyFiles.hash(book),StudyFiles.hash(restored));}try(ReaderStore reader=new ReaderStore(c)){assertEquals(1,reader.load(uri,2,source).marks.size());assertEquals("Marcador de teste",reader.bookmarks(uri).get(0)[3]);}try(PlusStore db=new PlusStore(c)){List<StudyStore.Row> notes=db.rows("voice_notes",null,null,null,10);assertEquals(1,notes.size());assertTrue(new File(notes.get(0).s("path")).isFile());assertNotEquals(voice.getPath(),notes.get(0).s("path"));assertEquals(1,db.rows("bible_verses",null,null,null,10).size());assertEquals(1,db.rows("book_collections",null,null,null,10).size());}assertEquals(2,c.getSharedPreferences("seeky",0).getInt("reader_page_"+uri,-1));assertEquals("test-only-backup-secret",c.getSharedPreferences("seeky",0).getString("personal_api_key",""));assertTrue(book.isFile());assertTrue(voice.isFile());assertFalse(WorkspaceBackup.pending(c).exists());assertFalse(WorkspaceEpoch.restoring);}
 @Test public void localRecoveryRestoresTheWorkspaceThatWasReplaced()throws Exception{write();try(StudyStore db=new StudyStore(c)){db.save("materials",material,StudyStore.values("progress",88));}try(WorkspaceBackup.Staged staged=stage()){WorkspaceBackup.restore(c,staged,()->false,s->{});}File root=new File(c.getFilesDir(),"workspace-recovery");File[] files=root.listFiles((d,n)->n.endsWith(".zip"));assertNotNull(files);assertEquals(1,files.length);try(WorkspaceBackup.Staged staged=WorkspaceBackup.stage(c,files[0],true,()->false,s->{})){WorkspaceBackup.restore(c,staged,()->false,s->{});}try(StudyStore db=new StudyStore(c)){assertEquals(88,db.get("materials",material).n("progress"));assertEquals(book.getPath(),db.get("materials",material).s("path"));}}
 @Test public void corruptionIsRejectedBeforeTheCurrentLibraryChanges()throws Exception{write();rewrite(null,true);try{stage();fail("Expected integrity rejection");}catch(IOException expected){assertTrue(expected.getMessage().contains("integridade"));}try(StudyStore db=new StudyStore(c)){assertEquals(37,db.get("materials",material).n("progress"));assertEquals(1,db.count("notes",null,null));}assertEquals(0,WorkspaceEpoch.value);assertTrue(book.isFile());}
 @Test public void traversalAndCredentialFieldsAreRejectedBeforeRestore()throws Exception{write();rewrite(root->{JSONArray entries=root.getJSONArray("entries");entries.getJSONObject(3).put("entry","../outside");},false);try{stage();fail();}catch(IOException expected){}write();rewrite(root->root.getJSONObject("preferences").getJSONObject("seeky").put("api_key",new JSONObject().put("type","string").put("value","not-a-real-key")),false);try{stage();fail();}catch(IOException expected){assertTrue(expected.getMessage().contains("privado"));}assertEquals(0,WorkspaceEpoch.value);}
 @Test public void cancellingBackupDoesNotModifyTheLibrary()throws Exception{try(OutputStream out=new FileOutputStream(archive)){try{WorkspaceBackup.write(c,out,false,()->true,s->{});fail();}catch(InterruptedIOException expected){}}try(StudyStore db=new StudyStore(c)){assertEquals(1,db.count("materials",null,null));}assertTrue(book.isFile());}
 @Test public void staleReaderScrollCannotOverwriteRestoredProgress()throws Exception{write();ReaderPosition position=new ReaderPosition(c.getSharedPreferences("seeky",0),new Handler(Looper.getMainLooper()));position.put("reader_page_"+uri,42);try(WorkspaceBackup.Staged staged=stage()){WorkspaceBackup.restore(c,staged,()->false,s->{});}position.flush();assertEquals(2,c.getSharedPreferences("seeky",0).getInt("reader_page_"+uri,-1));}
 @Test public void committedPreferencesFinishAfterAnInterruptedRestore()throws Exception{JSONObject prefs=WorkspaceBackup.preferences(c);c.getSharedPreferences("seeky",0).edit().putInt("reader_page_"+uri,77).apply();String token=UUID.randomUUID().toString();WorkspaceBackup.preparePending(c,token,prefs,Collections.emptyMap(),Collections.emptyList());try(PlusStore db=new PlusStore(c)){db.save("workspace_state",StudyStore.values("id",1,"token",token));}WorkspaceBackup.finishPending(c);assertEquals(2,c.getSharedPreferences("seeky",0).getInt("reader_page_"+uri,-1));assertFalse(WorkspaceBackup.pending(c).exists());}
 interface Edit{void apply(JSONObject root)throws Exception;}
 void rewrite(Edit edit,boolean corrupt)throws Exception{File target=new File(c.getCacheDir(),"workspace-mutated.zip");boolean changed=false;try(ZipFile zip=new ZipFile(archive);ZipOutputStream out=new ZipOutputStream(new FileOutputStream(target))){Enumeration<? extends ZipEntry> entries=zip.entries();while(entries.hasMoreElements()){ZipEntry entry=entries.nextElement();byte[] data;try(InputStream in=zip.getInputStream(entry)){data=ContentText.read(in,2000000);}if(entry.getName().equals("workspace.json")&&edit!=null){JSONObject root=new JSONObject(new String(data,"UTF-8"));edit.apply(root);data=root.toString().getBytes("UTF-8");}if(corrupt&&!changed&&entry.getName().startsWith("payload/")){data[0]^=1;changed=true;}out.putNextEntry(new ZipEntry(entry.getName()));out.write(data);out.closeEntry();}}Files.move(target.toPath(),archive.toPath(),java.nio.file.StandardCopyOption.REPLACE_EXISTING);}
}
